#!/usr/bin/env node
/**
 * Runs `prisma generate` only when the generated client is missing.
 *
 * This guards the postinstall hook so that repeated `pnpm install` calls
 * (e.g. adding a dependency) do not re-run the slow generation step when
 * the client artefacts are already present.
 *
 * To force regeneration (e.g. after a schema change), run:
 *   pnpm prisma:generate
 */

'use strict';

const { existsSync } = require('fs');
const { execSync } = require('child_process');
const { dirname, join } = require('path');

/**
 * Locate the `.prisma/client` marker generated by `prisma generate`.
 *
 * Under pnpm's isolated node_modules layout, `.prisma/client` is NOT hoisted
 * to the project root — it lives as a sibling of `@prisma/client` inside
 * whichever directory pnpm actually placed that package (e.g.
 * node_modules/.pnpm/@prisma+client@x.y.z/node_modules/.prisma/client).
 * A hardcoded `node_modules/.prisma/client` path only works for npm/yarn's
 * hoisted layout and silently never matches under pnpm, causing this guard
 * to think generation is needed even when the client is present (or, worse,
 * mask a genuinely missing client if generation is skipped elsewhere).
 *
 * Resolving relative to `require.resolve('@prisma/client')` follows
 * whatever module resolution actually put the package on disk, so it works
 * for both hoisted and isolated (pnpm) layouts.
 */
function findClientMarker() {
  try {
    const clientEntry = require.resolve('@prisma/client');
    // clientEntry is .../node_modules/@prisma/client/<entry file>
    const clientPkgDir = dirname(clientEntry);
    return join(clientPkgDir, '..', '..', '.prisma', 'client', 'index.js');
  } catch {
    // @prisma/client isn't resolvable yet (e.g. very first install) — fall
    // back to the legacy hoisted path so we still attempt generation.
    return join(__dirname, '..', 'node_modules', '.prisma', 'client', 'index.js');
  }
}

const CLIENT_MARKER = findClientMarker();

if (existsSync(CLIENT_MARKER)) {
  console.log('Prisma client already generated — skipping postinstall generation.');
  console.log('Run `pnpm prisma:generate` manually after a schema change.');
} else {
  console.log('Prisma client not found — running prisma generate...');
  execSync('prisma generate', { stdio: 'inherit' });
}
